package daily_assignments;

public class Assignment_07Oct2026_NumAndMultiplyBy5 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=5;
		int multiplyBy5=0;
		int i=1;
	
		while (i <= num) {
			multiplyBy5 = i * 5;
            System.out.println("Multiplication of " + i + " by 5 is : " + multiplyBy5);
            i++;
        }
	}

}
